import ast, json

ROOT = "/home/johnson/workspace/LLM_PostProcess"
CORPUS = f"{ROOT}/research/ai-infra-expert/corpus/train.jsonl"
EXP = f"{ROOT}/experiments/2026-08-17-teacher-b-corpus-review"
OUT = f"{EXP}/results/train-batch-0201.jsonl"
START = 2000
N = 10

src = open(f"{EXP}/scripts/tb_gen_batch_0200.py").read()
tree = ast.parse(src)
TP_PP_TAIL = None
for node in tree.body:
    if isinstance(node, ast.Assign) and getattr(node.targets[0], "id", "") == "TP_PP_TAIL":
        TP_PP_TAIL = ast.literal_eval(node.value)
assert TP_PP_TAIL and len(TP_PP_TAIL) > 2000

rows = [json.loads(l) for l in open(CORPUS) if l.strip()]
sel = rows[START:START + N]
assert len(sel) == N

STANCES = [
 ("Analytical stance under test: scheduler-interaction-and-chunked-prefill-first - the parallelism layout is evaluated through a scheduler whose policy can dominate the effect being measured.",
  "Falsifiable hypothesis H201a: the two layouts are compared under equivalent scheduler policy, testable by dumping the engine's effective scheduler configuration per arm - chunked prefill on or off, chunk size, max running sequences, max batched tokens, preemption policy - and diffing them. If the configurations differ, part of any measured latency delta is a scheduler effect rather than a parallelism effect and the comparison is confounded.",
  "Serving latency is produced jointly by the parallelism layout and the request scheduler, and modern engines set scheduler defaults as a function of the layout, so a naive A/B silently varies two things at once. Chunked prefill is the clearest case: it splits long prefills into token-budgeted chunks interleaved with decode steps, which lowers decode-step jitter and TPOT tail at the cost of TTFT, and whether it is enabled by default can differ between a tensor-parallel and a pipeline-parallel configuration. Max-batched-tokens and max-running-sequences are similarly derived from available KV blocks, which the layout changes, so the two arms can end up running different admission policies without anyone choosing that. The discipline is to dump the effective, runtime-resolved scheduler state per arm rather than the requested configuration, diff it field by field, and either equalise the policy or report the difference as a named, quantified confounder. Where equalising is impossible because a policy is not supported under one layout, that limitation is itself a finding and belongs in the comparison rather than in a footnote. Boundary condition: at low offered load the scheduler rarely queues and its policy is nearly inert, so this axis matters mainly at or above the knee of the load curve, which is exactly where the SLO-constrained operating point sits. ESTIMATE: chunked prefill trades TTFT for TPOT tail, so enabling it on one arm only can move the two metrics in opposite directions and produce a verdict that reverses when the policy is equalised; derivation is the reallocation of step time between prefill and decode work, and it is an ESTIMATE, not MEASURED.",
  0.64),

 ("Analytical stance under test: warmup-autotune-and-first-request-cost-first - the layout that ran second inherits a warm cache, and the layout that ran first pays the compilation bill.",
  "Falsifiable hypothesis H201b: measured latency is independent of arm ordering, testable by running the comparison twice with the arm order reversed and checking that the sign and magnitude of the delta are preserved. If reversing the order changes the verdict, the measurement is capturing warmup and autotune state rather than the parallelism layout.",
  "Parallelism layouts change kernel shapes, which changes which kernels are selected, compiled and autotuned, and that work happens on the first requests of a run. A tensor-parallel layout produces different per-device matrix shapes than a pipeline layout, so their compile-time and autotune costs differ, their cache hit rates differ, and any shared on-disk kernel cache warmed by the first arm can advantage the second. The failure mode is subtle because it does not look like an error: both arms complete, both report latency, and the delta is real but attributable to cache warmth rather than to the layout. Control it explicitly: declare a warmup phase with a stated request count or duration and exclude it from all statistics, clear or pin the kernel cache identically per arm and state which choice was made, run the arms in both orders, and report the order-reversal delta alongside the main result as an ordering-sensitivity check. Report time-to-first-healthy-request separately, since that number matters operationally for autoscaling and rolling deploys even though it is excluded from steady-state latency. Boundary condition: a long-lived service amortises warmup over hours and steady-state numbers are the decision-relevant ones; a service that scales up and down frequently pays warmup repeatedly and the cold-start cost belongs in the comparison as a first-class term. ESTIMATE: warmup cost is a fixed per-process charge, so its contribution to average latency falls roughly in inverse proportion to run length, which is why short runs exaggerate it and long runs hide it; derivation is amortising a constant over an increasing request count, and it is an ESTIMATE, not MEASURED.",
  0.63),

 ("Analytical stance under test: statistical-power-and-tail-estimation-first - a p99 claim needs enough independent samples to have a p99, and load-sweep runs frequently do not.",
  "Falsifiable hypothesis H201c: the run length per load point supports the tail quantile the SLO is written against, testable by computing the number of completed requests per arm per point and the bootstrap confidence interval width on the claimed quantile. If the interval is wider than the delta between arms, the comparison cannot distinguish the layouts at that quantile no matter how clean the rest of the design is.",
  "Latency SLOs are written against tails, and tails are the hardest statistic to estimate: the effective sample size for a p99 is roughly one percent of completed requests, so a run of a few hundred requests supports a p99 estimate built on a handful of observations whose confidence interval can easily exceed the entire effect being claimed. Two further properties of serving traces make it worse. Requests are not independent - queueing correlates neighbouring requests, so consecutive samples share state and the effective sample size is below the nominal count - and output lengths are heavy-tailed, so a few long generations dominate the tail and their placement in the trace is high-variance. The remedy is to compute rather than assume power: fix the trace and seed so both arms see the same arrival pattern and the same output-length draws, state the target quantile and the minimum detectable effect before running, size the run to that target, report bootstrap confidence intervals on every quantile claimed, and use block bootstrap or repeat-level resampling rather than naive per-request resampling to respect the correlation. Report the A/A noise floor at the same quantile so readers can see the resolution of the instrument. Boundary condition: median and mean latency need far fewer samples and are often adequate for early screening, so the cheap comparison at p50 can prune the candidate set before the expensive tail-resolution run. ESTIMATE: confidence interval width on an extreme quantile shrinks roughly with the square root of the number of samples in the tail region, so improving tail resolution by a factor requires that factor squared in run length; derivation is the standard error scaling of a quantile estimator, and it is an ESTIMATE, not MEASURED.",
  0.65),

 ("Analytical stance under test: request-trace-realism-and-output-length-distribution-first - a synthetic fixed-length benchmark can rank layouts in the opposite order to production traffic.",
  "Falsifiable hypothesis H201d: the layout ranking obtained under the benchmark trace is preserved under a replayed production trace, testable by running both layouts against a captured production arrival and length distribution and comparing the ranking to the synthetic result. If the ranking flips, the benchmark trace is not a valid proxy and no synthetic result should be promoted.",
  "The relative merits of tensor and pipeline parallelism depend heavily on the shape of the workload, so the trace is not a neutral backdrop, it is a decision variable. Fixed-length synthetic benchmarks - identical prompt length, identical output length, uniform arrival - eliminate exactly the properties that stress the layouts differently. Prompt-length variance drives prefill cost variance, which tensor parallelism absorbs by dividing compute and pipeline parallelism does not; output-length variance drives how long sequences occupy KV blocks and stage slots, which determines pipeline fill and scheduler churn; and arrival burstiness determines whether in-flight concurrency is ever high enough for a pipeline to fill at all. A trace with constant length and constant arrival can therefore show a pipeline layout at its best while production shows it at its worst. Capture the production distribution instead: joint prompt and output length distribution rather than marginals, since they correlate, arrival timestamps preserving burstiness rather than a Poisson approximation, and the mix of request types including any structured-output or long-context slice. Replay it at scaled rates for the load sweep, and report the trace's summary statistics alongside every result so the reader can judge transferability. Boundary condition: where production traffic is genuinely homogeneous, a synthetic trace matched to it is adequate and cheaper, but homogeneity must be demonstrated from a capture rather than assumed from the service description. ESTIMATE: pipeline utilisation depends on in-flight concurrency, so a bursty arrival pattern with the same mean rate as a uniform one spends more time both under-filled and queued, which widens the tail relative to the uniform case; derivation is the queueing response to variance at fixed mean, and it is an ESTIMATE, not MEASURED.",
  0.65),

 ("Analytical stance under test: cost-per-slo-satisfied-request-first - latency is a constraint and cost is the objective, and a layout that wins on latency can lose on the thing being optimised.",
  "Falsifiable hypothesis H201e: the layout with lower latency at the target also has lower cost per SLO-satisfied request, testable by computing, for each layout, the maximum sustained request rate at which the latency SLO still holds, dividing by the device count required, and comparing. If the faster layout serves fewer SLO-satisfied requests per device, choosing it on latency alone buys headroom the service does not need at a price it does not have to pay.",
  "A latency-sensitive service is not a latency-minimising service: the SLO defines a constraint boundary, and beyond it additional speed has little value while cost continues to accrue. The decision-relevant metric is therefore SLO-constrained throughput per device, obtained by sweeping offered load, finding for each layout the highest rate at which the target quantile still meets the SLO, and normalising by devices consumed. This reframing changes outcomes because the two layouts trade differently: tensor parallelism buys per-request speed by spending collective bandwidth on every layer, which reduces device efficiency at high load, while pipeline parallelism gives up per-request speed but avoids that per-layer tax and can serve more tokens per device once the stages are full. A layout that is fastest at concurrency one can therefore be the more expensive way to meet a p99 target at production load. Complete the accounting with the terms that survive the benchmark: replica count required to carry peak plus failure headroom, memory-driven limits on how much traffic each replica can hold, and any operational cost from a more complex layout such as longer recovery drills. Boundary condition: where the SLO cannot be met by the cheaper layout at any load, the constraint binds first and cost comparison is moot; that must be shown by measurement rather than assumed. ESTIMATE: cost per SLO-satisfied request is device count divided by the SLO-constrained rate, so a layout that is 20 percent faster per request but sustains a lower SLO-constrained rate per device is the more expensive choice; derivation is dividing devices by achieved constrained throughput, and it is an ESTIMATE, not MEASURED.",
  0.66),

 ("Analytical stance under test: engine-and-version-pinning-first - a layout comparison run across drifting software versions measures the release notes, not the parallelism.",
  "Falsifiable hypothesis H201f: both arms ran on byte-identical software and model artefacts, testable by recording and diffing engine version and build hash, kernel and communication library versions, driver version, container image digest and model checkpoint hash per arm. If any element differs, the delta is contaminated by a software change and the comparison must be re-run under pinned versions.",
  "Parallelism support is one of the fastest-moving areas of serving engines, so the temptation to compare a layout measured last month against one measured today is strong and the resulting number is uninterpretable. Between two engine releases, collective implementations change, kernel selection heuristics change, scheduler defaults change, and memory-allocator behaviour changes, and any of those can move latency by more than the effect under study. The control is mechanical: pin everything and prove the pin. Record engine version and build hash, communication and kernel library versions, driver and firmware versions, container image digest, model checkpoint hash and tokenizer hash, and emit them into the result artefact for every run so the diff is automatic rather than remembered. Run both arms within the same maintenance window on the same physical hosts where possible, since host-level differences in firmware, power policy and thermal state are a parallel contamination channel. When a version bump is itself the subject of interest, make it a separate, explicitly labelled arm rather than folding it into the layout comparison, so the two effects can be attributed independently. Boundary condition: where a needed layout is only supported in a newer engine version, the comparison unavoidably confounds version with layout, and the honest response is to state that and bound the version effect by re-measuring the incumbent layout on both versions. ESTIMATE: engine-version effects on serving latency are frequently of the same order as parallelism-layout effects, which is why an unpinned comparison has no power to attribute the delta; derivation is comparing typical release-to-release performance movement against the layout delta being claimed, and it is an ESTIMATE, not MEASURED.",
  0.64),

 ("Analytical stance under test: straggler-and-synchronisation-tail-first - collectives run at the speed of the slowest rank, so per-rank variance becomes end-to-end tail latency.",
  "Falsifiable hypothesis H201g: per-rank step times within each parallel group are homogeneous within a stated tolerance, testable by profiling per-rank compute and wait time at every collective and computing the distribution of maximum-minus-mean across steps. If a persistent straggler exists, the group's latency is set by it and the layout comparison is measuring rank imbalance rather than parallelism.",
  "A tensor-parallel group synchronises at every sharded block, which converts per-rank variance into group latency: every rank waits for the slowest, so the group's step time is the maximum over ranks rather than the mean, and the tail of the per-rank distribution propagates directly into the service's tail. Stragglers arise from causes that are invisible in aggregate metrics: thermal or power-cap throttling on one device, an unlucky NUMA or PCIe placement, a noisy co-tenant process, ECC retirement reducing effective memory bandwidth on one card, or an interrupt-heavy core pinned to one rank's host thread. The diagnostic that separates straggling from genuine collective cost is the split between exposed communication time and wait time: a rank that arrives early and waits is not slow, it is waiting for a slow peer, so per-rank wait-at-collective profiles localise the culprit immediately. Pipeline parallelism has an analogous but weaker coupling, since stages synchronise only at boundaries and per-microbatch, so a straggling stage inflates throughput cost but does not tax every layer. Measure per-rank compute and wait distributions across the full run, report maximum-minus-mean per step, and check the straggler's identity is stable, because a stable straggler indicates a hardware or placement defect while a rotating one indicates contention. Boundary condition: on a quiesced, homogeneous, well-cooled node with exclusive device access, straggling is small and this axis can be discharged by a short check; on shared or thermally constrained fleets it is often the dominant tail term. ESTIMATE: the expected maximum over a group grows with group size for any non-degenerate per-rank distribution, so wider tensor-parallel groups amplify a fixed per-rank variance into a larger step-time penalty; derivation is the order statistics of the maximum over independent draws, and it is an ESTIMATE, not MEASURED.",
  0.65),

 ("Analytical stance under test: rollout-mechanics-and-canary-routing-first - a layout change is a deployment change, and the deployment path is where latency-sensitive services actually break.",
  "Falsifiable hypothesis H201h: the new layout can be introduced and withdrawn without violating the latency SLO during the transition, testable by running a canary at a small traffic fraction with both layouts warm and measuring SLO compliance during ramp, steady state and rollback. If the transition itself breaches the SLO, the layout's steady-state advantage is not realisable without an availability cost that must be priced.",
  "Comparisons are usually written as if the winning layout appears instantaneously in production, but changing parallelism changes replica shape, device count per replica, warmup cost and memory footprint, and every one of those complicates the rollout. A replica that now needs more devices cannot be rolled in place if the fleet lacks spare capacity, so the transition either requires temporary over-provisioning or a capacity dip during which the remaining replicas absorb the full load - precisely the condition under which a latency SLO breaks. Design the rollout as part of the experiment: keep the incumbent layout warm and routable so rollback is a routing flip rather than a redeploy, start the canary at a traffic fraction small enough that its failure is absorbed by the incumbent, hold at each ramp step long enough to observe the tail quantile with adequate samples rather than long enough to feel comfortable, and pre-commit the abort conditions before the first request is shifted. Rehearse the revert once before the canary so its duration is measured rather than hoped. Watch the router as closely as the replicas, since load-balancing policies tuned for uniform replicas can misroute when replicas have different shapes and capacities, sending a disproportionate share to the canary and manufacturing a latency regression that is a routing artefact. Boundary condition: where fleet headroom is generous and replicas are interchangeable, the transition is low-risk and this axis is cheap to discharge; where capacity is tight it can dominate the decision. ESTIMATE: the observation time needed at each ramp step scales inversely with the canary traffic fraction for a fixed tail-quantile resolution, so small canaries need proportionally longer holds; derivation is requiring a fixed sample count in the tail at a reduced arrival rate, and it is an ESTIMATE, not MEASURED.",
  0.64),

 ("Analytical stance under test: observability-instrumentation-cost-and-blind-spot-first - the profiling needed to compare the layouts perturbs the thing being compared, and asymmetrically.",
  "Falsifiable hypothesis H201i: instrumentation overhead is equal across arms and small relative to the claimed delta, testable by running each layout with full profiling and with profiling disabled and comparing the latency difference per arm. If the overhead differs between arms or approaches the size of the effect, the measured delta is partly an artefact of the instrument.",
  "Attributing a latency difference to a parallelism layout requires per-step, per-rank timelines with collective boundaries, and that instrumentation is not free. Its cost is also not symmetric across layouts: a tensor-parallel layout emits collective events at every layer of every step, so a per-collective tracer generates far more events per unit time than a pipeline layout that synchronises only at stage boundaries, and the tracing overhead therefore penalises the arm with more collectives - the same arm whose collective cost is under investigation. Measure the instrument before trusting it: run each arm with and without profiling, report the per-arm overhead, and if it is comparable to the effect, switch to sampling profilers, counter-based aggregation or short profiling windows interleaved with unprofiled steady-state measurement, using the profiled windows for attribution and the unprofiled runs for the headline numbers. Note the complementary blind spot, which is that low-overhead aggregate metrics hide exactly the per-rank and per-stage structure that explains a delta, so a study that avoids profiling entirely can measure the difference accurately and be unable to explain it. The workable design uses both: unprofiled runs for the decision numbers, profiled windows for the mechanism, and an explicit statement of which numbers came from which. Boundary condition: counter-based collective statistics exposed by the communication library are usually cheap enough to leave on continuously and can carry much of the attribution burden without a full tracer. ESTIMATE: tracer overhead scales with event rate, and collective event rate under tensor parallelism scales with layer count per step while pipeline parallelism scales with stage boundaries per microbatch, so the overhead ratio between arms can be large; derivation is comparing per-step event counts under each layout, and it is an ESTIMATE, not MEASURED.",
  0.63),

 ("Analytical stance under test: decision-reversibility-and-lock-in-first - the two layouts differ in how cheaply the decision can be revisited, and that asymmetry should be priced before the performance numbers.",
  "Falsifiable hypothesis H201j: the layout choice is reversible within a stated time and cost budget, testable by measuring the end-to-end effort to move a live service from each layout back to the alternative, including checkpoint resharding, configuration change, capacity rebalancing and revalidation. If one direction is materially more expensive than the other, the cheaper-to-exit option deserves preference at equal measured performance.",
  "Performance comparisons are usually framed as one-shot decisions, but serving layouts are revisited as models, traffic and hardware change, so the cost of changing one's mind is a real term. The two axes are not symmetric in that respect. Tensor parallelism ties the deployment to a device group inside a high-bandwidth domain, so the degree is bounded by node topology and changing it is usually a configuration change plus a reshard and a revalidation. Pipeline parallelism ties the deployment to a layer partition, and if the partition has been tuned against measured per-layer cost, that tuning must be redone whenever the model, quantization, context length or hardware changes, so the maintenance burden recurs. Both accumulate lock-in through the surrounding system rather than the engine: autoscaling policies calibrated to replica shape, routing weights, capacity models, dashboards and alert thresholds all encode the current layout, and each is a small migration cost that is invisible at decision time and painful later. Price reversibility explicitly by rehearsing the reverse migration once, in staging, and recording its duration and manual steps; a layout whose reverse migration has never been executed should be treated as having an unbounded exit cost. Prefer the more reversible option where measured performance is within the noise floor, and state that preference as a decision rule before seeing results so it cannot be rationalised afterwards. Boundary condition: where one layout is forced by memory or topology constraints, reversibility is irrelevant and the constraint decides. ESTIMATE: exit cost grows with the number of downstream systems that encode replica shape, so a layout change touching autoscaling, routing and capacity models is materially more expensive than the engine flag suggests; derivation is counting the coupled systems that require recalibration, and it is an ESTIMATE, not MEASURED.",
  0.64),
]

assert len(STANCES) == N

RISKS = [
    "source_assistant restates a grading rubric instead of performing the comparison, so training on it teaches rubric recitation rather than analysis",
    "engines derive scheduler defaults from the layout, so an unequalised chunked-prefill or admission policy makes a scheduler effect look like a parallelism effect",
    "kernel autotune and cache warmth advantage whichever arm ran second, so an unreversed ordering can produce a verdict that flips on re-run",
    "tail quantile claims made on runs too short to populate the tail have confidence intervals wider than the effect being asserted",
    "fixed-length synthetic traces remove the prompt-length, output-length and burstiness variance that separate the layouts, and can reverse the ranking",
    "optimising latency past the SLO boundary buys unused headroom while cost per SLO-satisfied request, the actual objective, may favour the slower layout",
    "unpinned engine, kernel, driver or checkpoint versions between arms mean the measured delta may be a software release effect",
    "tensor-parallel groups synchronise every layer, so a single throttled or contended rank converts into end-to-end tail latency for the whole group",
    "the rollout itself can breach the SLO when replica shape and device count change without fleet headroom, and routers tuned for uniform replicas can misroute to the canary",
    "per-collective tracing costs more on the layout with more collectives, so instrumentation overhead is asymmetric and biases the arm under investigation",
    "layout decisions accumulate lock-in through autoscaling, routing and capacity models, so exit cost is larger than the engine configuration suggests",
]

EVIDENCE = [
    "the runtime-resolved scheduler configuration dumped per arm - chunked prefill state and chunk size, max batched tokens, max running sequences, preemption policy - with a field-by-field diff and any unequalisable difference quantified",
    "per-arm latency measured under both arm orderings with a declared warmup-exclusion rule, the kernel-cache handling stated, and time-to-first-healthy-request reported separately",
    "completed-request counts per arm per load point, the target quantile stated in advance with its minimum detectable effect, block-bootstrap confidence intervals on every quantile claimed, and the A/A noise floor at the same quantile",
    "a captured production trace with joint prompt and output length distribution and real arrival timestamps, replayed against both layouts, with the ranking compared against the synthetic-trace result",
    "SLO-constrained maximum sustained request rate per layout, divided by devices consumed, plus replica count required for peak and failure headroom",
    "engine version and build hash, communication and kernel library versions, driver and firmware versions, container image digest, checkpoint and tokenizer hashes recorded per arm and diffed automatically",
    "per-rank compute and wait-at-collective distributions across the run, maximum-minus-mean per step, and whether the straggler identity is stable or rotating",
    "a canary run at a stated traffic fraction with both layouts warm, SLO compliance measured during ramp, steady state and rollback, plus a rehearsed revert with its measured duration",
    "per-arm latency measured with and without profiling to quantify instrumentation overhead, with headline numbers taken from unprofiled runs and attribution from profiled windows, each labelled by source",
    "a rehearsed reverse migration in staging per layout recording duration, manual steps, resharding cost and the list of downstream systems requiring recalibration",
]

out = []
for rec, (stance, hyp, body, conf) in zip(sel, STANCES):
    m = {x["role"]: x["content"] for x in rec["messages"]}
    ans = f"{stance}\n\n{hyp}\n\n{body}\n\n{TP_PP_TAIL}"
    out.append({
        "source_id": rec["id"],
        "teacher_lane": "teacher-B",
        "teacher_model": "claude-opus-5-current",
        "calibration_status": "provisional",
        "decision": "rewrite",
        "source_user": m["user"],
        "source_assistant": m["assistant"],
        "corrected_answer": ans,
        "quality_dimensions": {
            "technical_correctness": 3,
            "instruction_coverage": 2,
            "operational_safety": 3,
        },
        "risks": RISKS,
        "evidence_required": EVIDENCE,
        "confidence": conf,
    })

with open(OUT, "w") as f:
    for r in out:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print("WROTE", OUT, len(out))
print("IDS", ",".join(r["source_id"] for r in out))
print("OPENINGS_DISTINCT", len({r["corrected_answer"][:200] for r in out}))
